119	/*
120	 * bisect_edge: split an edge without splitting the adjacent faces
121	 *  e: edge to split
122	 *
123	 * returns: added vertex
124	 *
125	 * We provide this as an example for how to implement local operations.
126	 * (and as a useful subroutine!)
127	 */
128	std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::bisect_edge(EdgeRef e) {
129		HalfedgeRef h = e->halfedge;   //h : v1 -> v2
130		HalfedgeRef t = h->twin;       //t : v2 -> v1
131		HalfedgeRef hn = h->next;
132		HalfedgeRef tn = t->next;
133		VertexRef v1 = h->vertex;
134		VertexRef v2 = t->vertex;
135	
136		//new elements: one vertex, two halfedges, one edge:
137		VertexRef m = emplace_vertex();
138		HalfedgeRef h2 = emplace_halfedge(); //h2 : m -> v2 (new edge)
139		HalfedgeRef t2 = emplace_halfedge(); //t2 : m -> v1 (on e)
140		EdgeRef e2 = emplace_edge(e->sharp);
141	
142		//data:
143		m->position = e->center();
144		interpolate_data({v1, v2}, m);
145		interpolate_data({h, hn}, h2); //dividing h -> (h, h2)
146		interpolate_data({t, tn}, t2); //dividing t -> (t, t2)
147	
148		//connectivity: h stays on e and becomes v1 -> m, t becomes v2 -> m and
149		// moves to the new edge e2:
150		h->twin = t2;
151		h->next = h2;
152		h2->set_tnvef(t, hn, m, e2, h->face);
153		t->twin = h2;
154		t->next = t2;
155		t->edge = e2;
156		t2->set_tnvef(h, tn, m, e, t->face);
157	
158		e->halfedge = h;
159		e2->halfedge = h2;
160		m->halfedge = h2;
161		//v1->halfedge and v2->halfedge still reference h and t, which still
162		// leave v1 and v2 respectively, so they remain valid.
163	
164		return m;
165	}
