168	/*
169	 * split_edge: split an edge and adjacent (non-boundary) faces
170	 *  e: edge to split
171	 *
172	 * returns: added vertex. vertex->halfedge should lie along e
173	 *
174	 * Note that when splitting the adjacent faces, the new edge
175	 * should connect to the vertex ccw from the ccw-most end of e
176	 * within the face.
177	 *
178	 * Do not split adjacent boundary faces.
179	 */
180	std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::split_edge(EdgeRef e) {
181		// A2L2 (REQUIRED): split_edge
182	
183		//first, bisect the edge:
184		std::optional<VertexRef> opt_m = bisect_edge(e);
185		if (!opt_m) return std::nullopt;
186		VertexRef m = *opt_m;
187	
188		//after bisection:
189		HalfedgeRef h = e->halfedge; //h  : v1 -> m  (on e)
190		HalfedgeRef t2 = h->twin;    //t2 : m  -> v1 (on e)
191		HalfedgeRef h2 = h->next;    //h2 : m  -> v2 (on the bisected-off edge)
192		HalfedgeRef t = h2->twin;    //t  : v2 -> m  (on the bisected-off edge)
193	
194		//split h's face (unless boundary) by connecting m to the vertex ccw from
195		// v2 (the ccw-most end of e within the face):
196		if (!h->face->boundary) {
197			FaceRef f = h->face;
198			HalfedgeRef hn = h2->next; //hn : v2 -> c
199			HalfedgeRef hc = hn->next; //hc : c -> ...
200			VertexRef c = hc->vertex;
201			HalfedgeRef hcn = hc->next;
202	
203			FaceRef f2 = emplace_face(false);    //will become {m, v2, c}
204			HalfedgeRef d = emplace_halfedge();  //d  : m -> c (in f)
205			HalfedgeRef dt = emplace_halfedge(); //dt : c -> m (in f2)
206			EdgeRef de = emplace_edge(false);
207	
208			d->set_tnvef(dt, hc, m, de, f);
209			dt->set_tnvef(d, h2, c, de, f2);
210			de->halfedge = d;
211	
212			h->next = d;
213			hn->next = dt;
214	
215			h2->face = f2;
216			hn->face = f2;
217			f2->halfedge = h2;
218			f->halfedge = h;
219	
220			interpolate_data({h, h2}, d);
221			interpolate_data({hc, hcn}, dt);
222		}
223	
224		//split t's face (unless boundary) by connecting m to the vertex ccw from
225		// v1 (the ccw-most end of e within that face):
226		if (!t->face->boundary) {
227			FaceRef g = t->face;
228			HalfedgeRef tn = t2->next; //tn : v1 -> c'
229			HalfedgeRef tc = tn->next; //tc : c' -> ...
230			VertexRef c2 = tc->vertex;
231			HalfedgeRef tcn = tc->next;
232	
233			FaceRef g2 = emplace_face(false);    //will become {m, v1, c'}
234			HalfedgeRef d = emplace_halfedge();  //d  : m -> c' (in g)
235			HalfedgeRef dt = emplace_halfedge(); //dt : c' -> m (in g2)
236			EdgeRef de = emplace_edge(false);
237	
238			d->set_tnvef(dt, tc, m, de, g);
239			dt->set_tnvef(d, t2, c2, de, g2);
240			de->halfedge = d;
241	
242			t->next = d;
243			tn->next = dt;
244	
245			t2->face = g2;
246			tn->face = g2;
247			g2->halfedge = t2;
248			g->halfedge = t;
249	
250			interpolate_data({t, t2}, d);
251			interpolate_data({tc, tcn}, dt);
252		}
253	
254		//the new vertex's halfedge should lie along the original edge:
255		m->halfedge = t2;
256	
257		return m;
258	}
