335	/*
336	 * extrude_face: creates a face inset into a face
337	 *  f: the face to inset
338	 *
339	 * returns: reference to the inner face
340	 *
341	 * see also [BEVEL NOTE] above.
342	 */
343	std::optional<Halfedge_Mesh::FaceRef> Halfedge_Mesh::extrude_face(FaceRef f) {
344		//A2L4: Extrude Face
345		// Reminder: This function does not update the vertex positions.
346		// Remember to also fill in extrude_helper (A2L4h)
347	
348		//collect the face's halfedges / vertices (ccw around f):
349		std::vector<HalfedgeRef> hs;
350		std::vector<VertexRef> vs;
351		{
352			HalfedgeRef h = f->halfedge;
353			do {
354				hs.push_back(h);
355				vs.push_back(h->vertex);
356				h = h->next;
357			} while (h != f->halfedge);
358		}
359		uint32_t n = static_cast<uint32_t>(hs.size());
360	
361		//per original halfedge: one new vertex, one inner edge, one spoke edge,
362		// four halfedges, and one quad side face:
363		std::vector<VertexRef> nvs(n);   //nvs[i]: inset copy of vs[i]
364		std::vector<HalfedgeRef> ih(n);  //ih[i] : v_i' -> v_j' (on f)
365		std::vector<HalfedgeRef> iht(n); //iht[i]: v_j' -> v_i' (on quad i)
366		std::vector<HalfedgeRef> sp(n);  //sp[i] : v_i  -> v_i' (on quad i-1)
367		std::vector<HalfedgeRef> spt(n); //spt[i]: v_i' -> v_i  (on quad i)
368		std::vector<EdgeRef> ie(n), se(n);
369		std::vector<FaceRef> quads(n);
370	
371		for (uint32_t i = 0; i < n; ++i) {
372			nvs[i] = emplace_vertex();
373			//new vertices start at the same positions as the originals
374			// (see [BEVEL NOTE]); extrude_positions() moves them later:
375			nvs[i]->position = vs[i]->position;
376			interpolate_data({vs[i]}, nvs[i]);
377	
378			ih[i] = emplace_halfedge();
379			iht[i] = emplace_halfedge();
380			sp[i] = emplace_halfedge();
381			spt[i] = emplace_halfedge();
382			ie[i] = emplace_edge(false);
383			se[i] = emplace_edge(false);
384			quads[i] = emplace_face(false);
385		}
386	
387		for (uint32_t i = 0; i < n; ++i) {
388			uint32_t j = (i + 1) % n;
389	
390			//quad i is [v_i, v_j, v_j', v_i']; it absorbs the original halfedge hs[i]:
391			hs[i]->next = sp[j];
392			hs[i]->face = quads[i];
393			sp[j]->set_tnvef(spt[j], iht[i], vs[j], se[j], quads[i]);
394			iht[i]->set_tnvef(ih[i], spt[i], nvs[j], ie[i], quads[i]);
395			spt[i]->set_tnvef(sp[i], hs[i], nvs[i], se[i], quads[i]);
396			quads[i]->halfedge = hs[i];
397	
398			//f becomes the inner face, edged by the ih[i] cycle:
399			ih[i]->set_tnvef(iht[i], ih[j], nvs[i], ie[i], f);
400	
401			ie[i]->halfedge = ih[i];
402			se[i]->halfedge = sp[i];
403			nvs[i]->halfedge = ih[i];
404			//vs[i]->halfedge remains valid since hs[i] still leaves vs[i].
405	
406			//corner data for new halfedges comes from the matching original corner:
407			interpolate_data({hs[i]}, ih[i]);  //corner at v_i'
408			interpolate_data({hs[j]}, iht[i]); //corner at v_j'
409			interpolate_data({hs[i]}, sp[i]);  //corner at v_i
410			interpolate_data({hs[i]}, spt[i]); //corner at v_i'
411		}
412		f->halfedge = ih[0];
413	
414		return f;
415	}
