417	/*
418	 * flip_edge: rotate non-boundary edge ccw inside its containing faces
419	 *  e: edge to flip
420	 *
421	 * if e is a boundary edge, does nothing and returns std::nullopt
422	 * if flipping e would create an invalid mesh, does nothing and returns std::nullopt
423	 *
424	 * otherwise returns the edge, post-rotation
425	 *
426	 * does not create or destroy mesh elements.
427	 */
428	std::optional<Halfedge_Mesh::EdgeRef> Halfedge_Mesh::flip_edge(EdgeRef e) {
429		//A2L1: Flip Edge - works for general polygon faces
430	
431		HalfedgeRef h = e->halfedge;   //h : a -> b (in f)
432		HalfedgeRef t = h->twin;       //t : b -> a (in g)
433		FaceRef f = h->face;
434		FaceRef g = t->face;
435	
436		//cannot flip an edge on the boundary:
437		if (f->boundary || g->boundary) return std::nullopt;
438	
439		VertexRef a = h->vertex;
440		VertexRef b = t->vertex;
441		HalfedgeRef hb = h->next;  //hb : b -> c
442		HalfedgeRef hc = hb->next; //hc : c -> ...
443		HalfedgeRef ta = t->next;  //ta : a -> d
444		HalfedgeRef td = ta->next; //td : d -> ...
445		VertexRef c = hc->vertex;
446		VertexRef d = td->vertex;
447	
448		//halfedges before h and t in their faces:
449		HalfedgeRef hp = hc;
450		while (hp->next != h) hp = hp->next;
451		HalfedgeRef tp = td;
452		while (tp->next != t) tp = tp->next;
453	
454		//--- validity checks ---
455		//rotating ccw, the edge would connect c and d:
456		if (c == d) return std::nullopt;
457		//d must not already be a vertex of f (f would touch d twice), and
458		// c must not already be a vertex of g:
459		{
460			HalfedgeRef x = f->halfedge;
461			do {
462				if (x->vertex == d) return std::nullopt;
463				x = x->next;
464			} while (x != f->halfedge);
465			x = g->halfedge;
466			do {
467				if (x->vertex == c) return std::nullopt;
468				x = x->next;
469			} while (x != g->halfedge);
470		}
471		//c and d must not already be connected by an edge (non-manifold result):
472		{
473			HalfedgeRef x = c->halfedge;
474			do {
475				if (x->twin->vertex == d) return std::nullopt;
476				x = x->twin->next;
477			} while (x != c->halfedge);
478		}
479	
480		//--- rewire (no elements are created or destroyed) ---
481		//h becomes d -> c and stays in f; t becomes c -> d and stays in g.
482		//f' runs c -> ... -> a -> d -> c (old chain, then ta, then h);
483		//g' runs d -> ... -> b -> c -> d (old chain, then hb, then t):
484		hp->next = ta;
485		ta->next = h;
486		h->next = hc;
487		h->vertex = d;
488	
489		tp->next = hb;
490		hb->next = t;
491		t->next = td;
492		t->vertex = c;
493	
494		ta->face = f;
495		hb->face = g;
496	
497		//fix halfedge pointers of the elements whose halfedge moved or was
498		// reassigned:
499		if (f->halfedge == hb) f->halfedge = h;
500		if (g->halfedge == ta) g->halfedge = t;
501		if (a->halfedge == h) a->halfedge = ta;
502		if (b->halfedge == t) b->halfedge = hb;
503	
504		return e;
505	}
