553	/* collapse_edge: collapse edge to a vertex at its middle
554	 *  e: the edge to collapse
555	 *
556	 * if collapsing the edge would result in an invalid mesh, does nothing and returns std::nullopt
557	 * otherwise returns the newly collapsed vertex
558	 */
559	std::optional<Halfedge_Mesh::VertexRef> Halfedge_Mesh::collapse_edge(EdgeRef e) {
560		//A2L3: Collapse Edge - general polygon version
561	
562		HalfedgeRef h = e->halfedge;   //h : a -> b (in f)
563		HalfedgeRef t = h->twin;       //t : b -> a (in g)
564		VertexRef a = h->vertex;       //survives as the merged vertex
565		VertexRef b = t->vertex;       //is erased
566		FaceRef f = h->face;
567		FaceRef g = t->face;
568		HalfedgeRef hn = h->next;
569		HalfedgeRef tn = t->next;
570	
571		//a boundary triangle would become a 2-gon:
572		if (f->boundary && f->degree() == 3) return std::nullopt;
573		if (g->boundary && g->degree() == 3) return std::nullopt;
574	
575		//an interior edge whose endpoints are both on the boundary would pinch
576		// the boundary into itself:
577		if (!f->boundary && !g->boundary && a->on_boundary() && b->on_boundary()) return std::nullopt;
578	
579		bool f_tri = !f->boundary && f->degree() == 3;
580		bool g_tri = !g->boundary && g->degree() == 3;
581		VertexRef cf = hn->next->vertex; //vertex ccw from b in f
582		VertexRef cg = tn->next->vertex; //vertex ccw from a in g
583		if (f_tri && g_tri && cf == cg) return std::nullopt; //two-triangle "fin"
584	
585		//collect outgoing halfedges of a and b before any rewiring:
586		std::vector<HalfedgeRef> a_out, b_out;
587		{
588			HalfedgeRef x = a->halfedge;
589			do {
590				a_out.push_back(x);
591				x = x->twin->next;
592			} while (x != a->halfedge);
593			x = b->halfedge;
594			do {
595				b_out.push_back(x);
596				x = x->twin->next;
597			} while (x != b->halfedge);
598		}
599	
600		//link condition: any vertex adjacent to both a and b must be the vertex
601		// opposite e in a triangle adjacent to e (its two edges to a and b get
602		// merged by the collapse instead of becoming duplicate edges):
603		{
604			std::unordered_set<VertexRef> neighbors_of_a;
605			for (HalfedgeRef x : a_out) neighbors_of_a.insert(x->twin->vertex);
606			for (HalfedgeRef x : b_out) {
607				VertexRef w = x->twin->vertex;
608				if (w == a || w == b) continue;
609				if (!neighbors_of_a.count(w)) continue;
610				if (!((f_tri && w == cf) || (g_tri && w == cg))) return std::nullopt;
611			}
612		}
613	
614		//no face other than f and g may touch both a and b (such a face would
615		// touch the merged vertex twice):
616		for (HalfedgeRef x : a_out) {
617			FaceRef k = x->face;
618			if (k == f || k == g) continue;
619			HalfedgeRef y = k->halfedge;
620			do {
621				if (y->vertex == b) return std::nullopt;
622				y = y->next;
623			} while (y != k->halfedge);
624		}
625	
626		//--- perform the collapse ---
627		//the merged vertex lands at the midpoint of the edge:
628		Vec3 mid = e->center();
629		interpolate_data({a, b}, a);
630		a->position = mid;
631	
632		HalfedgeRef a_he; //a surviving halfedge leaving a, for a->halfedge
633	
634		if (f_tri) {
635			//f degenerates; its other two edges are merged into e1:
636			HalfedgeRef h1 = hn;        //h1 : b  -> cf
637			HalfedgeRef h2 = hn->next;  //h2 : cf -> a
638			HalfedgeRef h1t = h1->twin; //h1t: cf -> b  (survives as cf -> m)
639			HalfedgeRef h2t = h2->twin; //h2t: a  -> cf (survives as m  -> cf)
640			EdgeRef e1 = h1->edge;
641			EdgeRef e2 = h2->edge;
642	
643			interpolate_data({h1t, h2}, h1t); //merged cf -> m corner
644			interpolate_data({h2t, h1}, h2t); //merged m -> cf corner
645	
646			h1t->twin = h2t;
647			h2t->twin = h1t;
648			h1t->edge = e1;
649			h2t->edge = e1;
650			e1->halfedge = h1t;
651			cf->halfedge = h1t;
652	
653			erase_halfedge(h);
654			erase_halfedge(h1);
655			erase_halfedge(h2);
656			erase_edge(e2);
657			erase_face(f);
658		} else {
659			//f just loses h:
660			HalfedgeRef hp = hn;
661			while (hp->next != h) hp = hp->next;
662			hp->next = hn;
663			if (f->halfedge == h) f->halfedge = hn;
664			erase_halfedge(h);
665		}
666	
667		if (g_tri) {
668			//g degenerates; its other two edges are merged into ge1:
669			HalfedgeRef g1 = tn;        //g1 : a  -> cg
670			HalfedgeRef g2 = tn->next;  //g2 : cg -> b
671			HalfedgeRef g1t = g1->twin; //g1t: cg -> a  (survives as cg -> m)
672			HalfedgeRef g2t = g2->twin; //g2t: b  -> cg (survives as m  -> cg)
673			EdgeRef ge1 = g1->edge;
674			EdgeRef ge2 = g2->edge;
675	
676			interpolate_data({g1t, g2}, g1t); //merged cg -> m corner
677			interpolate_data({g2t, g1}, g2t); //merged m -> cg corner
678	
679			g1t->twin = g2t;
680			g2t->twin = g1t;
681			g1t->edge = ge1;
682			g2t->edge = ge1;
683			ge1->halfedge = g1t;
684			cg->halfedge = g1t;
685	
686			erase_halfedge(t);
687			erase_halfedge(g1);
688			erase_halfedge(g2);
689			erase_edge(ge2);
690			erase_face(g);
691	
692			a_he = g2t; //survives; reassigned to a below
693		} else {
694			//g just loses t:
695			HalfedgeRef tp = tn;
696			while (tp->next != t) tp = tp->next;
697			tp->next = tn;
698			if (g->halfedge == t) g->halfedge = tn;
699			erase_halfedge(t);
700	
701			a_he = tn; //survives and leaves a
702		}
703	
704		//b's remaining outgoing halfedges now leave a (erased halfedges have
705		// their vertex set to vertices.end() and are skipped):
706		for (HalfedgeRef x : b_out) {
707			if (x->vertex == b) x->vertex = a;
708		}
709		a->halfedge = a_he;
710	
711		erase_vertex(b);
712		erase_edge(e);
713	
714		return a;
715	}
