779	/*
780	 * extrude_positions: compute new positions for the vertices of an extruded face
781	 *  face: the face that was created by the extrude operation
782	 *  move: how much to translate the face
783	 *  shrink: amount to linearly interpolate vertices in the face toward the face's centroid
784	 *    shrink of zero leaves the face where it is
785	 *    positive shrink makes the face smaller (at shrink of 1, face is a point)
786	 *    negative shrink makes the face larger
787	 *
788	 * only changes vertex positions (no connectivity changes!)
789	 *
790	 * This is called repeatedly as the user interacts, just after extrude_face.
791	 * (So you can assume the local topology is set up however your extrude_face function does it.)
792	 *
793	 * Using extrude face in the GUI will assume a shrink of 0 to only extrude the selected face
794	 * Using bevel face in the GUI will allow you to shrink and increase the size of the selected face
795	 * 
796	 * see also [BEVEL NOTE] above.
797	 */
798	void Halfedge_Mesh::extrude_positions(FaceRef face, Vec3 move, float shrink) {
799		//A2L4h: Extrude Positions Helper
800	
801		//'face' is the inner face created by extrude_face. For an inner halfedge
802		// h : v_i' -> v_j', h->twin lies on the side quad, h->twin->next is the
803		// spoke v_i' -> v_i, and its twin starts at the original vertex v_i --
804		// which still sits at the position v_i' started from.
805	
806		//centroid of the original (outer) ring of vertices:
807		Vec3 centroid;
808		float n = 0.0f;
809		{
810			HalfedgeRef h = face->halfedge;
811			do {
812				centroid += h->twin->next->twin->vertex->position;
813				n += 1.0f;
814				h = h->next;
815			} while (h != face->halfedge);
816			centroid /= n;
817		}
818	
819		//lerp each inner vertex from its original position toward the centroid
820		// by 'shrink', then translate by 'move':
821		HalfedgeRef h = face->halfedge;
822		do {
823			Vec3 orig = h->twin->next->twin->vertex->position;
824			h->vertex->position = orig + shrink * (centroid - orig) + move;
825			h = h->next;
826		} while (h != face->halfedge);
827	}
