223	template<class T> struct MutablePriorityQueue {
224		void insert(const T& item) {
225			queue.insert(item);
226		}
227		void remove(const T& item) {
228			if (queue.find(item) != queue.end()) {
229				queue.erase(item);
230			}
231		}
232		const T& top() const {
233			return *(queue.begin());
234		}
235		void pop() {
236			queue.erase(queue.begin());
237		}
238		size_t size() {
239			return queue.size();
240		}
241	
242		std::set<T> queue;
243	};
