297		//Collect the original elements before modifying anything
298		// (iterating the element lists while mutating them would be asking for trouble):
299		std::vector< VertexRef > original_vertices;
300		for (VertexRef v = vertices.begin(); v != vertices.end(); ++v) original_vertices.push_back(v);
301	
302		std::vector< EdgeRef > original_edges;
303		for (EdgeRef e = edges.begin(); e != edges.end(); ++e) original_edges.push_back(e);
304	
305		std::vector< FaceRef > original_faces;
306		for (FaceRef f = faces.begin(); f != faces.end(); ++f) {
307			if (!f->boundary) original_faces.push_back(f);
308		}
309	
310		//Bisect every original edge, remembering the vertex added on each edge.
311		// This does not divide any faces, so every non-boundary n-gon becomes a
312		// 2n-gon alternating original vertices (v_i) and edge-center vertices (m_i),
313		// and boundary faces simply absorb the extra halfedges.
314		std::unordered_map< EdgeCRef, VertexRef > edge_vertex;
315		std::unordered_set< VertexCRef > edge_vertices;
316		for (EdgeRef e : original_edges) {
317			std::optional< VertexRef > v = bisect_edge(e);
318			if (!v) continue; //should not happen on a valid mesh
319			edge_vertex.emplace(e, *v);
320			edge_vertices.insert(*v);
321		}
322	
323		//For every original non-boundary face, insert a center vertex and
324		// split the (now 2n-gon) face into n quads (v_i, m_i, center, m_{i-1}):
325		std::unordered_map< FaceCRef, VertexRef > face_vertex;
326		for (FaceRef f : original_faces) {
327			//collect the halfedges of f leaving original vertices, in ccw order:
328			// (A[i]: v_i -> m_i)
329			std::vector< HalfedgeRef > A;
330			{
331				HalfedgeRef h = f->halfedge;
332				do {
333					if (!edge_vertices.count(h->vertex)) A.push_back(h);
334					h = h->next;
335				} while (h != f->halfedge);
336			}
337			uint32_t n = static_cast<uint32_t>(A.size());
338			if (n < 3) continue; //not a valid face; leave it alone
339	
340			//grab everything the rewiring below will need *before* changing any pointers:
341			std::vector< HalfedgeCRef > face_halfedges; //for data interpolation
342			std::vector< VertexCRef > face_corners; //for data interpolation
343			std::vector< HalfedgeRef > D(n); //D[i]: m_{i-1} -> v_i
344			std::vector< VertexRef > M(n); //M[i]: the edge-center vertex m_i
345			{
346				HalfedgeRef h = f->halfedge;
347				do {
348					face_halfedges.push_back(h);
349					h = h->next;
350				} while (h != f->halfedge);
351			}
352			for (uint32_t i = 0; i < n; ++i) {
353				face_corners.push_back(A[i]->vertex);
354				M[i] = A[i]->next->vertex;
355				D[i] = A[(i + n - 1) % n]->next;
356			}
357	
358			//make the center vertex:
359			VertexRef center = emplace_vertex();
360			face_vertex.emplace(f, center);
361			interpolate_data(face_corners, center);
362	
363			//make the new "spoke" halfedges:
364			// B[i]: m_i -> center, C[i]: center -> m_{i-1} (B[i] and C[i+1] are twins, on spoke edge S[i])
365			std::vector< HalfedgeRef > B(n), C(n);
366			std::vector< EdgeRef > S(n);
367			for (uint32_t i = 0; i < n; ++i) {
368				B[i] = emplace_halfedge();
369				C[i] = emplace_halfedge();
370				S[i] = emplace_edge();
371				S[i]->halfedge = B[i];
372				interpolate_data(face_halfedges, B[i]);
373				interpolate_data(face_halfedges, C[i]);
374			}
375	
376			//rewire into quads; quad i is (v_i, m_i, center, m_{i-1}), ccw:
377			// A[i] -> B[i] -> C[i] -> D[i] -> (back to A[i])
378			for (uint32_t i = 0; i < n; ++i) {
379				FaceRef q = (i == 0) ? f : emplace_face(false);
380				q->halfedge = A[i];
381	
382				A[i]->next = B[i];
383				A[i]->face = q;
384				B[i]->set_tnvef(C[(i + 1) % n], C[i], M[i], S[i], q);
385				C[i]->set_tnvef(B[(i + n - 1) % n], D[i], center, S[(i + n - 1) % n], q);
386				D[i]->face = q; //D[i]->next already points at A[i]
387			}
388			center->halfedge = C[0];
389		}
390	
391		//finally, assign positions from the parameter maps:
392		for (VertexRef v : original_vertices) {
393			if (auto p = vertex_positions.find(v); p != vertex_positions.end()) {
394				v->position = p->second;
395			}
396		}
397		for (auto const &[e, v] : edge_vertex) {
398			if (auto p = edge_vertex_positions.find(e); p != edge_vertex_positions.end()) {
399				v->position = p->second;
400			}
401		}
402		for (auto const &[f, v] : face_vertex) {
403			if (auto p = face_vertex_positions.find(f); p != face_vertex_positions.end()) {
404				v->position = p->second;
405			}
406		}
407	}
