409	/*
410	 * flip_orientation: flip direction of all halfedges
411	 *
412	 * works on all valid meshes.
413	 */
414	void Halfedge_Mesh::flip_orientation() {
415		//remember each halfedge's current vertex so that updates don't
416		// interfere with each other:
417		std::unordered_map< HalfedgeRef, VertexRef > old_vertex;
418		for (HalfedgeRef h = halfedges.begin(); h != halfedges.end(); ++h) {
419			old_vertex.emplace(h, h->vertex);
420		}
421	
422		//reverse every face cycle; each halfedge keeps its edge, face, and twin,
423		// but traverses its edge in the opposite direction:
424		for (FaceRef f = faces.begin(); f != faces.end(); ++f) {
425			//collect the cycle while the next pointers are still the old ones:
426			std::vector< HalfedgeRef > cycle;
427			HalfedgeRef h = f->halfedge;
428			do {
429				cycle.push_back(h);
430				h = h->next;
431			} while (h != f->halfedge);
432			//each halfedge now follows its predecessor and leaves from
433			// the vertex its twin used to leave from:
434			for (size_t i = 0; i < cycle.size(); ++i) {
435				cycle[i]->next = cycle[(i + cycle.size() - 1) % cycle.size()];
436				cycle[i]->vertex = old_vertex[cycle[i]->twin];
437			}
438		}
439	
440		//make each vertex->halfedge point at a halfedge that (now) leaves the vertex:
441		for (HalfedgeRef h = halfedges.begin(); h != halfedges.end(); ++h) {
442			h->vertex->halfedge = h;
443		}
444	}
