void Halfedge_Mesh::set_corner_normals(float threshold) {

	//classify edges as sharp (smoothing-group boundary) or smooth:
	auto edge_sharp = [&](EdgeCRef e) -> bool {
		if (threshold >= 180.0f) return false; //smooth mode: everything smooth
		if (threshold <= 0.0f) return true;    //flat mode: everything sharp
		if (e->sharp) return true;
		if (e->halfedge->face->boundary || e->halfedge->twin->face->boundary) return true;
		float cos_angle = dot(e->halfedge->face->normal().unit(),
		                      e->halfedge->twin->face->normal().unit());
		cos_angle = std::min(1.0f, std::max(-1.0f, cos_angle));
		float angle = std::acos(cos_angle) * 180.0f / PI_F;
		return angle > threshold;
	};

	for (VertexRef v = vertices.begin(); v != vertices.end(); ++v) {
		//collect the corners at v on non-boundary faces:
		std::vector< HalfedgeRef > corners;
		{
			HalfedgeRef h = v->halfedge;
			do {
				if (!h->face->boundary) corners.push_back(h);
				h = h->twin->next;
			} while (h != v->halfedge);
		}

		//flood-fill smoothing groups: two corners at v are in the same group
		// if they are adjacent around v across a smooth edge. Walking
		// h -> h->twin->next visits every corner at v in one cycle, so
		// following only these forward links reaches the whole group.
		std::unordered_set< HalfedgeRef > visited;
		for (HalfedgeRef c : corners) {
			if (visited.count(c)) continue;
			Vec3 n;
			std::vector< HalfedgeRef > stack{c};
			std::vector< HalfedgeRef > group;
			visited.insert(c);
			while (!stack.empty()) {
				HalfedgeRef h = stack.back();
				stack.pop_back();
				group.push_back(h);
				n += h->face->normal(); //area-weighted face normal
				HalfedgeRef nx = h->twin->next;
				if (!edge_sharp(h->edge) && !nx->face->boundary && !visited.count(nx)) {
					visited.insert(nx);
					stack.push_back(nx);
				}
			}
			Vec3 normal = n.unit();
			for (HalfedgeRef h : group) h->corner_normal = normal;
		}
	}

	//boundary corners have no smoothing group; give them their own face's normal:
	for (HalfedgeRef h = halfedges.begin(); h != halfedges.end(); ++h) {
		if (h->face->boundary) h->corner_normal = h->face->normal().unit();
	}
}

