void Halfedge_Mesh::set_corner_uvs_per_face() {

	for (FaceRef f = faces.begin(); f != faces.end(); ++f) {
		if (f->boundary) {
			HalfedgeRef h = f->halfedge;
			do {
				h->corner_uv = Vec2(0.0f, 0.0f);
				h = h->next;
			} while (h != f->halfedge);
			continue;
		}

		//tangent plane perpendicular to the face normal:
		Vec3 n = f->normal().unit();
		//pick the global axis least aligned with n to build a stable basis:
		Vec3 axis;
		if (std::abs(n.x) <= std::abs(n.y) && std::abs(n.x) <= std::abs(n.z)) {
			axis = Vec3(1.0f, 0.0f, 0.0f);
		} else if (std::abs(n.y) <= std::abs(n.z)) {
			axis = Vec3(0.0f, 1.0f, 0.0f);
		} else {
			axis = Vec3(0.0f, 0.0f, 1.0f);
		}
		Vec3 u = cross(axis, n).unit();
		Vec3 w = cross(n, u);

		//project each corner position onto the (u, w) frame:
		HalfedgeRef h = f->halfedge;
		do {
			h->corner_uv = Vec2(dot(h->vertex->position, u), dot(h->vertex->position, w));
			h = h->next;
		} while (h != f->halfedge);
	}
}

