void Halfedge_Mesh::triangulate() {
	//A2G1: triangulation

	//collect faces to split first (the operation adds faces to the list):
	std::vector< FaceRef > to_split;
	for (FaceRef f = faces.begin(); f != faces.end(); ++f) {
		if (!f->boundary && f->degree() > 3) to_split.push_back(f);
	}

	for (FaceRef f : to_split) {
		//collect the face's halfedges, in ccw order:
		std::vector< HalfedgeRef > hs;
		{
			HalfedgeRef h = f->halfedge;
			do {
				hs.push_back(h);
				h = h->next;
			} while (h != f->halfedge);
		}
		uint32_t n = static_cast<uint32_t>(hs.size());

		//fan triangulation around v0: triangles are (v0, v_i, v_{i+1})
		// for i = 1 .. n-2. Diagonal a_i : v0 -> v_i, twin b_i : v_i -> v0.
		VertexRef v0 = hs[0]->vertex;
		std::vector< HalfedgeCRef > face_halfedges(hs.begin(), hs.end());

		HalfedgeRef prev_b; //b_{i} of the previous iteration (v_i -> v0)
		for (uint32_t i = 2; i <= n - 1; ++i) {
			//face for triangle (v0, v_{i-1}, v_i); the last triangle reuses f:
			FaceRef nf = (i == n - 1) ? f : emplace_face(false);

			HalfedgeRef a; //a_i : v0 -> v_i (not needed for the last triangle)
			HalfedgeRef b; //b_i : v_i -> v0
			if (i < n - 1) {
				a = emplace_halfedge();
				b = emplace_halfedge();
				EdgeRef e = emplace_edge(false);
				e->halfedge = a;
				a->set_tnvef(b, hs[i - 1], v0, e, nf);
				b->set_tnvef(a, (i == 2) ? hs[0] : prev_b, hs[i]->vertex, e,
				             (i == 2) ? f : prev_b->face);
				interpolate_data(face_halfedges, a);
				interpolate_data(face_halfedges, b);
			} else {
				b = hs[n - 1]; //last triangle closes with the original halfedge
				b->face = nf;
			}

			hs[i - 1]->next = hs[i % n]; //v_{i-1} -> v_i -> (v_{i+1} or v0)
			hs[i - 1]->face = nf;
			hs[i % n]->face = nf;
			if (i < n - 1) {
				hs[i - 1]->next = hs[i];
				hs[i]->next = b;
				hs[i]->face = nf;
				b->next = a;
				a->next = hs[i - 1];
				//fix: a : v0 -> v_i enters this triangle from v0:
				a->face = nf;
				a->next = hs[i - 1];
				hs[i - 1]->next = a;
				//triangle (v0, v_{i-1}, v_i) is: a? no -- see below
			}
			nf->halfedge = hs[i - 1];
			prev_b = b;
		}
	}
}

