// Faces
//new face vertices go at the centroid of the face's vertices:
for (FaceRef f = faces.begin(); f != faces.end(); ++f) {
	if (!f->boundary) face_vertex_positions[f] = f->center();
}

// Edges
//new edge vertices go at the average of the edge's endpoints and the
// centroids of its two adjacent faces; boundary edges just use the midpoint:
for (EdgeRef e = edges.begin(); e != edges.end(); ++e) {
	if (e->on_boundary()) {
		edge_vertex_positions[e] = e->center();
	} else {
		edge_vertex_positions[e] = 0.25f * (e->halfedge->vertex->position +
		                                    e->halfedge->twin->vertex->position +
		                                    e->halfedge->face->center() +
		                                    e->halfedge->twin->face->center());
	}
}

// Vertices
//interior vertex with n adjacent faces moves to (Q + 2R + (n-3)S) / n,
// where Q is the average of adjacent face centroids, R the average of
// adjacent edge midpoints, and S the original position.
//boundary vertex moves to (6S + b1 + b2) / 8, where b1, b2 are its two
// neighbors along the boundary:
for (VertexRef v = vertices.begin(); v != vertices.end(); ++v) {
	if (v->on_boundary()) {
		Vec3 neighbors;
		HalfedgeRef h = v->halfedge;
		do {
			if (h->edge->on_boundary()) neighbors += h->twin->vertex->position;
			h = h->twin->next;
		} while (h != v->halfedge);
		vertex_positions[v] = (6.0f * v->position + neighbors) / 8.0f;
	} else {
		Vec3 Q, R;
		float n = 0.0f;
		HalfedgeRef h = v->halfedge;
		do {
			Q += h->face->center();
			R += h->edge->center();
			n += 1.0f;
			h = h->twin->next;
		} while (h != v->halfedge);
		Q /= n;
		R /= n;
		vertex_positions[v] = (Q + 2.0f * R + (n - 3.0f) * v->position) / n;
	}
}

