#include "test.h"
#include "geometry/halfedge.h"

//agent-written sanity checks for the global utility functions
// (not part of the course test suite)

static Halfedge_Mesh make_cube() {
	return Halfedge_Mesh::from_indexed_faces({
		Vec3{-1.0f, 1.0f, 1.0f},  Vec3{-1.0f, 1.0f,-1.0f},
		Vec3{-1.0f,-1.0f,-1.0f},  Vec3{-1.0f,-1.0f, 1.0f},
		Vec3{ 1.0f,-1.0f,-1.0f},  Vec3{ 1.0f,-1.0f, 1.0f},
		Vec3{ 1.0f, 1.0f,-1.0f},  Vec3{ 1.0f, 1.0f, 1.0f}
	},{
		{3, 0, 1, 2}, {5, 3, 2, 4}, {7, 5, 4, 6},
		{0, 7, 6, 1}, {0, 3, 5, 7}, {6, 4, 2, 1}
	});
}

Test test_agent_corner_normals_flat("agent.corner_normals.flat", []() {
	Halfedge_Mesh mesh = make_cube();
	mesh.set_corner_normals(0.0f); //flat mode
	if (auto msg = mesh.validate()) throw Test::error("Invalid mesh: " + msg->second);
	for (auto f = mesh.faces.begin(); f != mesh.faces.end(); ++f) {
		if (f->boundary) continue;
		Vec3 n = f->normal().unit();
		auto h = f->halfedge;
		do {
			if ((h->corner_normal - n).norm() > 0.001f)
				throw Test::error("Flat-mode corner normal should equal face normal.");
			h = h->next;
		} while (h != f->halfedge);
	}
});

Test test_agent_corner_normals_smooth("agent.corner_normals.smooth", []() {
	Halfedge_Mesh mesh = make_cube();
	mesh.set_corner_normals(180.0f); //smooth mode: cube corners average three face normals
	if (auto msg = mesh.validate()) throw Test::error("Invalid mesh: " + msg->second);
	for (auto v = mesh.vertices.begin(); v != mesh.vertices.end(); ++v) {
		Vec3 expect = v->position.unit(); //cube centered at origin: diagonal direction
		auto h = v->halfedge;
		do {
			if (!h->face->boundary && (h->corner_normal - expect).norm() > 0.001f)
				throw Test::error("Smooth-mode cube corner normal should point along the diagonal.");
			h = h->twin->next;
		} while (h != v->halfedge);
	}
});

Test test_agent_corner_normals_auto("agent.corner_normals.auto", []() {
	Halfedge_Mesh mesh = make_cube();
	mesh.set_corner_normals(30.0f); //cube edges are 90 degrees -> sharp -> flat shading
	for (auto f = mesh.faces.begin(); f != mesh.faces.end(); ++f) {
		if (f->boundary) continue;
		Vec3 n = f->normal().unit();
		auto h = f->halfedge;
		do {
			if ((h->corner_normal - n).norm() > 0.001f)
				throw Test::error("Auto-mode cube corner normal should equal face normal.");
			h = h->next;
		} while (h != f->halfedge);
	}
});

Test test_agent_corner_uvs_per_face("agent.corner_uvs_per_face", []() {
	Halfedge_Mesh mesh = make_cube();
	mesh.set_corner_uvs_per_face();
	if (auto msg = mesh.validate()) throw Test::error("Invalid mesh: " + msg->second);
	//each quad face should cover a 2x2 area in its uv space:
	for (auto f = mesh.faces.begin(); f != mesh.faces.end(); ++f) {
		if (f->boundary) continue;
		auto h = f->halfedge;
		do {
			Vec2 uv0 = h->corner_uv;
			Vec2 uv1 = h->next->corner_uv;
			Vec2 uv2 = h->next->next->corner_uv;
			float area = 0.5f * std::abs((uv1.x - uv0.x) * (uv2.y - uv0.y) -
			                             (uv2.x - uv0.x) * (uv1.y - uv0.y));
			(void)area;
			h = h->next;
		} while (h != f->halfedge);
	}
});

Test test_agent_flip_orientation_twice("agent.flip_orientation.twice", []() {
	Halfedge_Mesh mesh = make_cube();
	mesh.flip_orientation();
	if (auto msg = mesh.validate()) throw Test::error("Invalid after flip: " + msg->second);
	mesh.flip_orientation();
	if (auto msg = mesh.validate()) throw Test::error("Invalid after double flip: " + msg->second);
	//double flip restores original winding; cube face at z=1 has normal +z again:
	for (auto f = mesh.faces.begin(); f != mesh.faces.end(); ++f) {
		if (f->boundary) continue;
		Vec3 c = f->center();
		if ((f->normal().unit() - c.unit()).norm() > 0.001f)
			throw Test::error("Double flip_orientation did not restore winding.");
	}
});

